//! The error codes of the protocol and the error type commands fail with.

use std::fmt;

/// Every code a failure response may carry (SPEC section 2).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Code {
    InvalidRequest,
    MissingParameter,
    InvalidParameterValue,
    QueueNameInvalid,
    QueueAlreadyExists,
    QueueDoesNotExist,
    ReceiptHandleInvalid,
    ReceiptHandleExpired,
    UnsupportedOperation,
    LimitExceeded,
}

impl Code {
    pub fn as_str(self) -> &'static str {
        match self {
            Code::InvalidRequest => "InvalidRequest",
            Code::MissingParameter => "MissingParameter",
            Code::InvalidParameterValue => "InvalidParameterValue",
            Code::QueueNameInvalid => "QueueNameInvalid",
            Code::QueueAlreadyExists => "QueueAlreadyExists",
            Code::QueueDoesNotExist => "QueueDoesNotExist",
            Code::ReceiptHandleInvalid => "ReceiptHandleInvalid",
            Code::ReceiptHandleExpired => "ReceiptHandleExpired",
            Code::UnsupportedOperation => "UnsupportedOperation",
            Code::LimitExceeded => "LimitExceeded",
        }
    }
}

#[derive(Debug)]
pub struct Error {
    pub code: Code,
    pub message: String,
}

impl Error {
    pub fn new(code: Code, message: impl Into<String>) -> Self {
        Self { code, message: message.into() }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}: {}", self.code.as_str(), self.message)
    }
}

impl std::error::Error for Error {}

pub type Result<T> = std::result::Result<T, Error>;
EOF
cat > src/params.rs <<'EOF'
//! Typed access to the members of a command object.
//!
//! A member whose value is `null` counts as absent everywhere (SPEC section 1).

use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Code, Error, Result};

pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    pub fn is_present(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    /// Fails with `MissingParameter` for the first of `names` that is absent.
    /// Called before any value is checked, as the error order demands.
    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|n| !self.is_present(n)) {
            Some(name) => Err(Error::new(Code::MissingParameter, format!("{name} is required"))),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|v| v.as_str().ok_or_else(|| wrong_type(name, "a string")))
            .transpose()
    }

    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|v| v.as_bool().ok_or_else(|| wrong_type(name, "a boolean")))
            .transpose()
    }

    pub fn object(&self, name: &str) -> Result<Option<&'a Map<String, Value>>> {
        self.get(name)
            .map(|v| v.as_object().ok_or_else(|| wrong_type(name, "an object")))
            .transpose()
    }

    /// An integer written without fraction or exponent, within `range`.
    pub fn integer(&self, name: &str, range: RangeInclusive<u64>) -> Result<Option<u64>> {
        let Some(value) = self.get(name) else { return Ok(None) };
        // serde_json parses `30.0` and `3e1` as floats, which `as_u64` rejects.
        let n = value.as_u64().ok_or_else(|| wrong_type(name, "an integer"))?;
        if !range.contains(&n) {
            let (lo, hi) = (range.start(), range.end());
            return Err(invalid(format!("{name} must be between {lo} and {hi}")));
        }
        Ok(Some(n))
    }

    pub fn required_string(&self, name: &str) -> Result<&'a str> {
        self.string(name)?.ok_or_else(|| missing(name))
    }

    /// A string of 1 to 128 characters from `A-Z a-z 0-9 _ -`.
    pub fn identifier(&self, name: &str) -> Result<Option<&'a str>> {
        let Some(s) = self.string(name)? else { return Ok(None) };
        if !(1..=128).contains(&s.len()) || !s.bytes().all(is_name_byte) {
            return Err(invalid(format!("{name} must be 1 to 128 characters from A-Z a-z 0-9 _ -")));
        }
        Ok(Some(s))
    }
}

pub fn is_name_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_' || b == b'-'
}

fn missing(name: &str) -> Error {
    Error::new(Code::MissingParameter, format!("{name} is required"))
}

pub fn invalid(message: impl Into<String>) -> Error {
    Error::new(Code::InvalidParameterValue, message)
}

fn wrong_type(name: &str, expected: &str) -> Error {
    invalid(format!("{name} must be {expected}"))
}
EOF
cat > src/lib.rs <<'EOF'
//! miniq: a small in-memory message queue driven by JSON commands.

pub mod error;
pub mod params;
EOF
cat > src/main.rs <<'EOF'
fn main() {}
EOF
