cat > src/queue.rs <<'EOF'
//! One queue: its attributes, its messages in arrival order and its bookkeeping.

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::ops::Bound;

use serde_json::{Map, Value};

use crate::error::Result;
use crate::params::{Params, invalid};

pub const MAX_MESSAGES: usize = 100_000;
const DEDUP_WINDOW: u64 = 300;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Config {
    pub visibility_timeout: u64,
    pub delay_seconds: u64,
    pub retention_seconds: u64,
    pub fifo: bool,
    pub content_based_dedup: bool,
    pub dead_letter: Option<DeadLetter>,
}

/// The attributes named in a request; `None` means "not given".
#[derive(Debug, Default)]
pub struct AttributeUpdate {
    pub visibility_timeout: Option<u64>,
    pub delay_seconds: Option<u64>,
    pub retention_seconds: Option<u64>,
    pub fifo: Option<bool>,
    pub content_based_dedup: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u64>,
}

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

impl AttributeUpdate {
    pub fn parse(members: &Map<String, Value>) -> Result<Self> {
        if let Some(unknown) = members.keys().find(|k| !ATTRIBUTE_NAMES.contains(&k.as_str())) {
            return Err(invalid(format!("unknown attribute {unknown}")));
        }
        let p = Params::new(members);
        Ok(Self {
            visibility_timeout: p.integer("VisibilityTimeout", 0..=43_200)?,
            delay_seconds: p.integer("DelaySeconds", 0..=900)?,
            retention_seconds: p.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: p.boolean("Fifo")?,
            content_based_dedup: p.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: p.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: p.integer("MaxReceiveCount", 1..=1000)?,
        })
    }

    /// The dead-letter configuration, which must be given completely or not at all.
    pub fn dead_letter(&self) -> Result<Option<DeadLetter>> {
        match (&self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => {
                Ok(Some(DeadLetter { queue: queue.clone(), max_receive_count }))
            }
            (None, None) => Ok(None),
            _ => Err(invalid("DeadLetterQueue and MaxReceiveCount must be given together")),
        }
    }
}

impl Config {
    /// The configuration a new queue gets: defaults for everything not given.
    pub fn with_defaults(update: &AttributeUpdate, dead_letter: Option<DeadLetter>) -> Self {
        Self {
            visibility_timeout: update.visibility_timeout.unwrap_or(30),
            delay_seconds: update.delay_seconds.unwrap_or(0),
            retention_seconds: update.retention_seconds.unwrap_or(345_600),
            fifo: update.fifo.unwrap_or(false),
            content_based_dedup: update.content_based_dedup.unwrap_or(false),
            dead_letter,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Delayed,
    InFlight,
    Visible,
}

#[derive(Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    /// The message is visible from this time on. Before it, the message is
    /// delayed if it was never delivered and in flight otherwise.
    pub available_at: u64,
    /// The latest receipt handle, if the message was delivered.
    pub handle: Option<u64>,
    pub receive_count: u64,
    pub first_received_at: Option<u64>,
    pub group: Option<String>,
    pub sequence: Option<u64>,
}

impl Message {
    pub fn state(&self, now: u64) -> State {
        if now >= self.available_at {
            State::Visible
        } else if self.handle.is_none() {
            State::Delayed
        } else {
            State::InFlight
        }
    }
}

/// What a delivery reports to the receiver.
pub struct Delivery {
    pub id: u64,
    pub handle: u64,
    pub body: String,
    pub receive_count: u64,
    pub sent_at: u64,
    pub first_received_at: u64,
    pub group: Option<String>,
    pub sequence: Option<u64>,
}

/// The record of an accepted FIFO send, kept for deduplication.
#[derive(Clone, Copy)]
pub struct Accepted {
    pub at: u64,
    pub id: u64,
    pub sequence: u64,
}

pub struct Queue {
    pub config: Config,
    /// Keyed by a per-queue arrival counter, so iteration is arrival order.
    messages: BTreeMap<u64, Message>,
    /// `(sent_at, key)` of every message, to find the expired ones cheaply.
    by_age: BTreeSet<(u64, u64)>,
    /// Latest receipt handle to the key of its message.
    handles: HashMap<u64, u64>,
    next_key: u64,
    next_sequence: u64,
    dedup: HashMap<String, Accepted>,
}

impl Queue {
    pub fn new(config: Config) -> Self {
        Self {
            config,
            messages: BTreeMap::new(),
            by_age: BTreeSet::new(),
            handles: HashMap::new(),
            next_key: 0,
            next_sequence: 1,
            dedup: HashMap::new(),
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    /// Removes the messages whose retention has run out at `now`.
    pub fn expire(&mut self, now: u64) {
        let Some(oldest_kept) = now.checked_sub(self.config.retention_seconds) else { return };
        // A message is gone once `sent_at <= now - retention`.
        while let Some(&(sent_at, key)) = self.by_age.first() {
            if sent_at > oldest_kept {
                break;
            }
            self.remove(key);
        }
    }

    pub fn counts(&self, now: u64) -> [u64; 3] {
        let mut counts = [0; 3];
        for m in self.messages.values() {
            counts[m.state(now) as usize] += 1;
        }
        counts
    }

    /// Adds `message` at the end of the queue and returns its sequence number
    /// if this is a FIFO queue.
    pub fn push(&mut self, mut message: Message) -> Option<u64> {
        message.sequence = self.config.fifo.then(|| {
            self.next_sequence += 1;
            self.next_sequence - 1
        });
        let sequence = message.sequence;
        self.by_age.insert((message.sent_at, self.next_key));
        self.messages.insert(self.next_key, message);
        self.next_key += 1;
        sequence
    }

    fn remove(&mut self, key: u64) -> Message {
        let message = self.messages.remove(&key).expect("key comes from the index");
        self.by_age.remove(&(message.sent_at, key));
        if let Some(handle) = message.handle {
            self.handles.remove(&handle);
        }
        message
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.by_age.clear();
        self.handles.clear();
    }

    /// A send with this deduplication id that is still inside its window.
    pub fn duplicate_of(&self, dedup_id: &str, now: u64) -> Option<Accepted> {
        self.dedup.get(dedup_id).copied().filter(|a| now - a.at < DEDUP_WINDOW)
    }

    pub fn remember(&mut self, dedup_id: &str, accepted: Accepted) {
        self.dedup.insert(dedup_id.to_owned(), accepted);
    }

    /// The key of the message that `handle` is the latest handle of, if it is in flight.
    fn in_flight(&self, handle: u64, now: u64) -> Option<u64> {
        let key = *self.handles.get(&handle)?;
        (self.messages[&key].state(now) == State::InFlight).then_some(key)
    }

    /// Returns whether a message was found and deleted.
    pub fn delete(&mut self, handle: u64, now: u64) -> bool {
        let Some(key) = self.in_flight(handle, now) else { return false };
        self.remove(key);
        true
    }

    /// Returns whether a message was found and its timeout replaced.
    pub fn change_visibility(&mut self, handle: u64, now: u64, timeout: u64) -> bool {
        let Some(key) = self.in_flight(handle, now) else { return false };
        self.messages.get_mut(&key).expect("key comes from the index").available_at = now + timeout;
        true
    }

    /// Delivers up to `max` messages (SPEC section 6). Messages that exceeded the
    /// receive count are removed and returned for the caller to dead-letter.
    pub fn receive(
        &mut self,
        now: u64,
        max: usize,
        timeout: u64,
        next_handle: &mut u64,
    ) -> (Vec<Delivery>, Vec<Message>) {
        let mut delivered = Vec::new();
        let mut dead = Vec::new();
        // Groups that still have an earlier message in the queue.
        let mut blocked_groups = HashSet::new();
        let mut cursor = Bound::Unbounded;
        while delivered.len() < max {
            let Some((&key, m)) = self.messages.range((cursor, Bound::Unbounded)).next() else {
                break;
            };
            cursor = Bound::Excluded(key);
            let eligible = m.state(now) == State::Visible
                && !m.group.as_ref().is_some_and(|g| blocked_groups.contains(g));
            let exhausted = self
                .config
                .dead_letter
                .as_ref()
                .is_some_and(|d| m.receive_count >= d.max_receive_count);
            if eligible && exhausted {
                dead.push(self.remove(key));
                continue;
            }
            if let Some(group) = &m.group {
                blocked_groups.insert(group.clone());
            }
            if !eligible {
                continue;
            }
            let m = self.messages.get_mut(&key).expect("key was just found");
            if let Some(old) = m.handle {
                self.handles.remove(&old);
            }
            let handle = *next_handle;
            *next_handle += 1;
            m.handle = Some(handle);
            m.receive_count += 1;
            m.available_at = now + timeout;
            let first_received_at = *m.first_received_at.get_or_insert(now);
            self.handles.insert(handle, key);
            delivered.push(Delivery {
                id: m.id,
                handle,
                body: m.body.clone(),
                receive_count: m.receive_count,
                sent_at: m.sent_at,
                first_received_at,
                group: m.group.clone(),
                sequence: m.sequence,
            });
        }
        (delivered, dead)
    }
}
EOF
