    fn default() -> Self {
        Self { now: 0, queues: HashMap::new(), next_message: 1, next_handle: 1 }
    }
}

impl Service {
    pub fn new() -> Self {
        Self::default()
    }

    /// Runs one input line (without its `\n`) and returns the response line.
    pub fn handle_line(&mut self, line: &[u8]) -> String {
        let response = match self.run(line) {
            Ok(mut members) => {
                members.insert("ok".into(), Value::Bool(true));
                Value::Object(members)
            }
            Err(e) => json!({
                "ok": false,
                "error": { "code": e.code.as_str(), "message": e.message },
            }),
        };
        response.to_string()
    }

    fn run(&mut self, line: &[u8]) -> Result<Output> {
        let request_error = |why: &str| Error::new(Code::InvalidRequest, why);
        let Ok(Value::Object(members)) = serde_json::from_slice(line) else {
            return Err(request_error("line is not a JSON object"));
        };
        let Some(Value::String(command)) = members.get("Command") else {
            return Err(request_error("Command must be a string"));
        };
        let p = Params::new(&members);
        match command.as_str() {
            "CreateQueue" => self.create_queue(&p),
            "SetQueueAttributes" => self.set_queue_attributes(&p),
            "GetQueueAttributes" => self.get_queue_attributes(&p),
            "ListQueues" => self.list_queues(&p),
            "DeleteQueue" => self.delete_queue(&p),
            "PurgeQueue" => self.purge_queue(&p),
            "Tick" => self.tick(&p),
            "SendMessage" => self.send_message(&p),
            "ReceiveMessage" => self.receive_message(&p),
            "DeleteMessage" => self.delete_message(&p),
            "ChangeMessageVisibility" => self.change_message_visibility(&p),
            other => Err(request_error(&format!("unknown command {other}"))),
        }
    }

    fn create_queue(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        if !is_valid_queue_name(name) {
            return Err(Error::new(Code::QueueNameInvalid, format!("invalid queue name {name:?}")));
        }
        let update = match p.object("Attributes")? {
            Some(members) => AttributeUpdate::parse(members)?,
            None => AttributeUpdate::default(),
        };
        let fifo = update.fifo.unwrap_or(false);
        if name.ends_with(".fifo") != fifo {
            return Err(Error::new(
                Code::QueueNameInvalid,
                "the .fifo suffix and the Fifo attribute must agree",
            ));
        }
        if update.content_based_dedup == Some(true) && !fifo {
            return Err(invalid("ContentBasedDeduplication needs a FIFO queue"));
        }
        let config = Config::with_defaults(&update, update.dead_letter()?);
        if let Some(existing) = self.queues.get(name) {
            return if existing.config == config {
                Ok(Output::new())
            } else {
                Err(Error::new(Code::QueueAlreadyExists, "queue exists with different attributes"))
            };
        }
        if let Some(dead_letter) = &config.dead_letter {
            let target = self.existing_queue(&dead_letter.queue)?;
            if target.config.fifo != fifo {
                return Err(invalid("the dead-letter queue must be of the same type"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(Code::LimitExceeded, "too many queues"));
        }
        self.queues.insert(name.to_owned(), Queue::new(config));
        Ok(Output::new())
    }

    fn set_queue_attributes(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName", "Attributes"])?;
        let name = p.required_string("QueueName")?;
        let members = p.object("Attributes")?.expect("required above");
        let update = AttributeUpdate::parse(members)?;
        let queue = lookup(&mut self.queues, self.now, name)?;
        if update.fifo.is_some() {
            return Err(Error::new(Code::UnsupportedOperation, "the type of a queue cannot change"));
        }
        if update.content_based_dedup == Some(true) && !queue.config.fifo {
            return Err(invalid("ContentBasedDeduplication needs a FIFO queue"));
        }
        let dead_letter = update.dead_letter()?;
        let fifo = queue.config.fifo;
        if let Some(d) = &dead_letter {
            let target = self.queues.get(&d.queue).ok_or_else(|| no_such_queue(&d.queue))?;
            if d.queue == name || target.config.fifo != fifo {
                return Err(invalid("invalid dead-letter queue"));
            }
        }
        let config = &mut self.queues.get_mut(name).expect("looked up above").config;
        config.visibility_timeout = update.visibility_timeout.unwrap_or(config.visibility_timeout);
        config.delay_seconds = update.delay_seconds.unwrap_or(config.delay_seconds);
        config.retention_seconds = update.retention_seconds.unwrap_or(config.retention_seconds);
        config.content_based_dedup = update.content_based_dedup.unwrap_or(config.content_based_dedup);
        config.dead_letter = dead_letter.or(config.dead_letter.take());
        Ok(Output::new())
    }

    fn get_queue_attributes(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let queue = lookup(&mut self.queues, self.now, name)?;
        let c = &queue.config;
        let mut attributes = json!({
            "VisibilityTimeout": c.visibility_timeout,
            "DelaySeconds": c.delay_seconds,
            "RetentionSeconds": c.retention_seconds,
            "Fifo": c.fifo,
            "ContentBasedDeduplication": c.content_based_dedup,
        });
        if let Some(d) = &c.dead_letter {
            attributes["DeadLetterQueue"] = json!(d.queue);
            attributes["MaxReceiveCount"] = json!(d.max_receive_count);
        }
        let [delayed, in_flight, visible] = queue.counts(self.now);
        Ok(output(json!({
            "Attributes": attributes,
            "Counts": { "Visible": visible, "InFlight": in_flight, "Delayed": delayed },
        })))
    }

    fn list_queues(&mut self, p: &Params) -> Result<Output> {
        let prefix = p.string("Prefix")?.unwrap_or("");
        let mut names: Vec<_> = self.queues.keys().filter(|n| n.starts_with(prefix)).collect();
        names.sort();
        Ok(output(json!({ "QueueNames": names })))
    }

    fn delete_queue(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        lookup(&mut self.queues, self.now, name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.config.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                queue.config.dead_letter = None;
            }
        }
        Ok(Output::new())
    }

    fn purge_queue(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        lookup(&mut self.queues, self.now, name)?.purge();
        Ok(Output::new())
    }

    fn tick(&mut self, p: &Params) -> Result<Output> {
        p.require(&["Seconds"])?;
        self.now += p.integer("Seconds", 0..=1_209_600)?.expect("required above");
        Ok(output(json!({ "Now": self.now })))
    }

    fn send_message(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName", "Body"])?;
        let name = p.required_string("QueueName")?;
        let body = p.required_string("Body")?;
        if !(1..=1024).contains(&body.len()) {
            return Err(invalid("Body must be 1 to 1024 bytes"));
        }
        let delay = p.integer("DelaySeconds", 0..=900)?;
        let group = p.identifier("GroupId")?;
        let dedup_id = p.identifier("DeduplicationId")?;
        let now = self.now;
        let queue = lookup(&mut self.queues, now, name)?;
        let fifo = queue.config.fifo;
        if (!fifo && (group.is_some() || dedup_id.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(Code::UnsupportedOperation, "not supported by this type of queue"));
        }
        let mut dedup_key = None;
        if fifo {
            let Some(group) = group else {
                return Err(Error::new(Code::MissingParameter, "GroupId is required"));
            };
            let key = match dedup_id {
                Some(id) => id,
                None if queue.config.content_based_dedup => body,
                None => return Err(Error::new(Code::MissingParameter, "DeduplicationId is required")),
            };
            if let Some(original) = queue.duplicate_of(key, now) {
                return Ok(sent(original.id, Some(original.sequence)));
            }
            dedup_key = Some((key, group));
        }
        if queue.len() >= MAX_MESSAGES {
            return Err(Error::new(Code::LimitExceeded, "queue is full"));
        }
        let id = self.next_message;
        self.next_message += 1;
        let delay = delay.unwrap_or(queue.config.delay_seconds);
        let sequence = queue.push(Message {
            id,
            body: body.to_owned(),
            sent_at: now,
            available_at: now + delay,
            handle: None,
            receive_count: 0,
            first_received_at: None,
            group: dedup_key.map(|(_, group)| group.to_owned()),
            sequence: None,
        });
        if let (Some((key, _)), Some(sequence)) = (dedup_key, sequence) {
            queue.remember(key, Accepted { at: now, id, sequence });
        }
        Ok(sent(id, sequence))
    }

    fn receive_message(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let max = p.integer("MaxMessages", 1..=10)?.unwrap_or(1);
        let timeout = p.integer("VisibilityTimeout", 0..=43_200)?;
        let now = self.now;
        let queue = lookup(&mut self.queues, now, name)?;
        let timeout = timeout.unwrap_or(queue.config.visibility_timeout);
        let dead_letter = queue.config.dead_letter.clone();
        let (delivered, dead) = queue.receive(now, max as usize, timeout, &mut self.next_handle);
        if let Some(dead_letter) = dead_letter {
            let target = self.queues.get_mut(&dead_letter.queue).expect("deleting a queue clears references to it");
            for mut message in dead {
                message.receive_count = 0;
                message.first_received_at = None;
                message.available_at = 0;
                message.handle = None;
                target.push(message);
            }
            target.expire(now);
        }
        let messages: Vec<Value> = delivered.into_iter().map(delivery_json).collect();
        Ok(output(json!({ "Messages": messages })))
    }

    fn delete_message(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName", "ReceiptHandle"])?;
        let name = p.required_string("QueueName")?;
        let handle = p.required_string("ReceiptHandle")?;
        let queue = lookup(&mut self.queues, self.now, name)?;
        let handle = issued_handle(handle, self.next_handle)?;
        if queue.delete(handle, self.now) { Ok(Output::new()) } else { Err(expired()) }
    }

    fn change_message_visibility(&mut self, p: &Params) -> Result<Output> {
        p.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
        let name = p.required_string("QueueName")?;
        let handle = p.required_string("ReceiptHandle")?;
        let timeout = p.integer("VisibilityTimeout", 0..=43_200)?.expect("required above");
        let queue = lookup(&mut self.queues, self.now, name)?;
        let handle = issued_handle(handle, self.next_handle)?;
        if queue.change_visibility(handle, self.now, timeout) { Ok(Output::new()) } else { Err(expired()) }
    }

    fn existing_queue(&self, name: &str) -> Result<&Queue> {
        self.queues.get(name).ok_or_else(|| no_such_queue(name))
    }
}

/// Finds a queue and drops its expired messages, so callers see it as of `now`.
/// Takes the map rather than `&mut Service` so callers can use other fields meanwhile.
fn lookup<'a>(queues: &'a mut HashMap<String, Queue>, now: u64, name: &str) -> Result<&'a mut Queue> {
    let queue = queues.get_mut(name).ok_or_else(|| no_such_queue(name))?;
    queue.expire(now);
    Ok(queue)
}

fn no_such_queue(name: &str) -> Error {
    Error::new(Code::QueueDoesNotExist, format!("no queue named {name:?}"))
}

fn expired() -> Error {
    Error::new(Code::ReceiptHandleExpired, "receipt handle is not that of a message in flight")
}

/// `r-<n>` in canonical form, for an `n` that has been issued.
fn issued_handle(text: &str, next_handle: u64) -> Result<u64> {
    text.strip_prefix("r-")
        .filter(|digits| !digits.starts_with('0') && digits.bytes().all(|b| b.is_ascii_digit()))
        .and_then(|digits| digits.parse::<u64>().ok())
        .filter(|n| (1..next_handle).contains(n))
        .ok_or_else(|| Error::new(Code::ReceiptHandleInvalid, "receipt handle was never issued"))
}

fn is_valid_queue_name(name: &str) -> bool {
    let stem = name.strip_suffix(".fifo").unwrap_or(name);
    let stem_max = if stem.len() == name.len() { 80 } else { 75 };
    (1..=stem_max).contains(&stem.len()) && stem.bytes().all(is_name_byte)
}

fn output(value: Value) -> Output {
    match value {
        Value::Object(members) => members,
        _ => unreachable!("responses are built from object literals"),
    }
}

fn sent(id: u64, sequence: Option<u64>) -> Output {
    let mut out = output(json!({ "MessageId": format!("m-{id}") }));
    if let Some(sequence) = sequence {
        out.insert("SequenceNumber".into(), json!(sequence));
    }
    out
}

fn delivery_json(d: Delivery) -> Value {
    let mut out = output(json!({
        "MessageId": format!("m-{}", d.id),
        "ReceiptHandle": format!("r-{}", d.handle),
        "Body": d.body,
        "ReceiveCount": d.receive_count,
        "SentAt": d.sent_at,
        "FirstReceivedAt": d.first_received_at,
    }));
    if let Some(group) = d.group {
        out.insert("GroupId".into(), json!(group));
    }
    if let Some(sequence) = d.sequence {
        out.insert("SequenceNumber".into(), json!(sequence));
    }
    Value::Object(out)
}
