fn send(svc: &mut Service, queue: &str, body: &str) -> Value {
    run(svc, &json!({"Command": "SendMessage", "QueueName": queue, "Body": body}).to_string())
}

fn receive(svc: &mut Service, queue: &str) -> Value {
    run(svc, &json!({"Command": "ReceiveMessage", "QueueName": queue}).to_string())
