use miniq::service::Service;
use serde_json::{Value, json};

fn run(svc: &mut Service, line: &str) -> Value {
    serde_json::from_str(&svc.handle_line(line.as_bytes())).expect("response is JSON")
}

fn code(response: &Value) -> &str {
    assert_eq!(response["ok"], false, "{response}");
    response["error"]["code"].as_str().expect("error code")
}

fn create(svc: &mut Service, name: &str, attrs: Value) -> Value {
    run(svc, &json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attrs}).to_string())
}

fn send(svc: &mut Service, queue: &str, body: &str) -> Value {
    run(svc, &json!({"Command": "SendMessage", "QueueName": queue, "Body": body}).to_string())
}

fn receive(svc: &mut Service, queue: &str) -> Value {
    run(svc, &json!({"Command": "ReceiveMessage", "QueueName": queue}).to_string())
}

fn tick(svc: &mut Service, seconds: u64) {
    run(svc, &json!({"Command": "Tick", "Seconds": seconds}).to_string());
}

#[test]
fn malformed_lines_are_invalid_requests() {
    let mut svc = Service::new();
    for line in ["", "[]", "{", r#"{"Command": 1}"#, r#"{"Command": "Nope"}"#, "{} {}"] {
        assert_eq!(code(&run(&mut svc, line)), "InvalidRequest", "{line:?}");
    }
    let response: Value = serde_json::from_str(&svc.handle_line(b"{\"Command\":\"Tick\",\"Seconds\":1}\xff")).unwrap();
    assert_eq!(code(&response), "InvalidRequest");
}

#[test]
fn integers_must_be_written_without_fraction_or_exponent() {
    let mut svc = Service::new();
    for seconds in ["30.0", "3e1", "\"30\"", "-1"] {
        let line = format!(r#"{{"Command": "Tick", "Seconds": {seconds}}}"#);
        assert_eq!(code(&run(&mut svc, &line)), "InvalidParameterValue", "{seconds}");
    }
    assert_eq!(run(&mut svc, r#"{"Command":"Tick","Seconds":30}"#), json!({"ok": true, "Now": 30}));
}

#[test]
fn missing_parameters_win_over_bad_values() {
    let mut svc = Service::new();
    let response = run(&mut svc, r#"{"Command":"SendMessage","Body":5}"#);
    assert_eq!(code(&response), "MissingParameter");
}

#[test]
fn create_queue_is_idempotent_only_for_equal_attributes() {
    let mut svc = Service::new();
    assert_eq!(create(&mut svc, "a", json!({})), json!({"ok": true}));
    assert_eq!(create(&mut svc, "a", json!({"VisibilityTimeout": 30})), json!({"ok": true}));
    assert_eq!(code(&create(&mut svc, "a", json!({"VisibilityTimeout": 31}))), "QueueAlreadyExists");
    assert_eq!(code(&create(&mut svc, "b.fifo", json!({}))), "QueueNameInvalid");
    assert_eq!(code(&create(&mut svc, "bad name", json!({}))), "QueueNameInvalid");
    assert_eq!(code(&create(&mut svc, "c", json!({"Bogus": 1}))), "InvalidParameterValue");
    assert_eq!(code(&create(&mut svc, "c", json!({"DeadLetterQueue": "a"}))), "InvalidParameterValue");
    assert_eq!(
        code(&create(&mut svc, "c", json!({"DeadLetterQueue": "zz", "MaxReceiveCount": 2}))),
        "QueueDoesNotExist"
    );
}

#[test]
fn list_queues_sorts_by_byte_value() {
    let mut svc = Service::new();
    for name in ["b", "_", "A", "a-1", "a.fifo", "1"] {
        let attrs = if name.ends_with(".fifo") { json!({"Fifo": true}) } else { json!({}) };
        assert_eq!(create(&mut svc, name, attrs)["ok"], true);
    }
    let all = run(&mut svc, r#"{"Command":"ListQueues"}"#);
    assert_eq!(all["QueueNames"], json!(["1", "A", "_", "a-1", "a.fifo", "b"]));
    let some = run(&mut svc, r#"{"Command":"ListQueues","Prefix":"a"}"#);
    assert_eq!(some["QueueNames"], json!(["a-1", "a.fifo"]));
}

#[test]
fn receive_hides_message_until_visibility_timeout_ends() {
    let mut svc = Service::new();
    create(&mut svc, "q", json!({"VisibilityTimeout": 10}));
    assert_eq!(send(&mut svc, "q", "hi"), json!({"ok": true, "MessageId": "m-1"}));
    let first = receive(&mut svc, "q");
    assert_eq!(
        first["Messages"],
        json!([{"MessageId": "m-1", "ReceiptHandle": "r-1", "Body": "hi",
                "ReceiveCount": 1, "SentAt": 0, "FirstReceivedAt": 0}])
    );
    assert_eq!(receive(&mut svc, "q")["Messages"], json!([]));
    tick(&mut svc, 10);
    let again = receive(&mut svc, "q");
    assert_eq!(again["Messages"][0]["ReceiveCount"], 2);
    assert_eq!(again["Messages"][0]["ReceiptHandle"], "r-2");
}

#[test]
fn receipt_handles_are_invalid_or_expired() {
    let mut svc = Service::new();
    create(&mut svc, "q", json!({}));
    create(&mut svc, "other", json!({}));
    send(&mut svc, "q", "x");
    receive(&mut svc, "q");
    let delete = |svc: &mut Service, queue: &str, handle: &str| {
        run(svc, &json!({"Command": "DeleteMessage", "QueueName": queue, "ReceiptHandle": handle}).to_string())
    };
    for handle in ["r-01", "R-1", "r-1 ", "r-2", "r-0", ""] {
        assert_eq!(code(&delete(&mut svc, "q", handle)), "ReceiptHandleInvalid", "{handle:?}");
    }
    assert_eq!(code(&delete(&mut svc, "other", "r-1")), "ReceiptHandleExpired");
    assert_eq!(delete(&mut svc, "q", "r-1"), json!({"ok": true}));
    assert_eq!(code(&delete(&mut svc, "q", "r-1")), "ReceiptHandleExpired");
}

#[test]
fn change_visibility_to_zero_makes_the_message_visible_at_once() {
    let mut svc = Service::new();
    create(&mut svc, "q", json!({}));
    send(&mut svc, "q", "x");
    receive(&mut svc, "q");
    let change = run(
        &mut svc,
        r#"{"Command":"ChangeMessageVisibility","QueueName":"q","ReceiptHandle":"r-1","VisibilityTimeout":0}"#,
    );
    assert_eq!(change, json!({"ok": true}));
    assert_eq!(receive(&mut svc, "q")["Messages"][0]["ReceiveCount"], 2);
