#[test]
fn retention_removes_messages_whatever_their_state() {
    let mut svc = Service::new();
    create(&mut svc, "q", json!({"RetentionSeconds": 60}));
    send(&mut svc, "q", "x");
    tick(&mut svc, 59);
    let counts = |svc: &mut Service| run(svc, r#"{"Command":"GetQueueAttributes","QueueName":"q"}"#)["Counts"].clone();
    assert_eq!(counts(&mut svc), json!({"Visible": 1, "InFlight": 0, "Delayed": 0}));
    tick(&mut svc, 1);
    assert_eq!(counts(&mut svc), json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

#[test]
fn fifo_deduplicates_for_300_seconds_without_extending_the_window() {
    let mut svc = Service::new();
    create(&mut svc, "q.fifo", json!({"Fifo": true}));
    let send = |svc: &mut Service| {
        run(svc, r#"{"Command":"SendMessage","QueueName":"q.fifo","Body":"b","GroupId":"g","DeduplicationId":"d"}"#)
    };
    let original = send(&mut svc);
    assert_eq!(original, json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    tick(&mut svc, 299);
    assert_eq!(send(&mut svc), original);
    tick(&mut svc, 1);
    assert_eq!(send(&mut svc), json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
}

#[test]
fn fifo_delivers_one_message_per_group_in_order() {
    let mut svc = Service::new();
    create(&mut svc, "q.fifo", json!({"Fifo": true, "ContentBasedDeduplication": true}));
    for (body, group) in [("a1", "a"), ("a2", "a"), ("b1", "b")] {
        let line = json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": body, "GroupId": group});
        run(&mut svc, &line.to_string());
    }
    let got = run(&mut svc, r#"{"Command":"ReceiveMessage","QueueName":"q.fifo","MaxMessages":10}"#);
    let bodies: Vec<_> = got["Messages"].as_array().unwrap().iter().map(|m| m["Body"].clone()).collect();
    assert_eq!(bodies, [json!("a1"), json!("b1")]);
}

#[test]
fn messages_over_the_receive_count_move_to_the_dead_letter_queue() {
    let mut svc = Service::new();
    create(&mut svc, "dlq", json!({}));
    create(&mut svc, "q", json!({"VisibilityTimeout": 0, "DeadLetterQueue": "dlq", "MaxReceiveCount": 1}));
    send(&mut svc, "q", "x");
    assert_eq!(receive(&mut svc, "q")["Messages"][0]["ReceiveCount"], 1);
    assert_eq!(receive(&mut svc, "q")["Messages"], json!([]));
    let moved = receive(&mut svc, "dlq");
    assert_eq!(moved["Messages"][0]["MessageId"], "m-1");
    assert_eq!(moved["Messages"][0]["ReceiveCount"], 1);
}

